package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Desc  string `json:"description"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	tmpl = template.Must(template.New("product").Parse(`
		<html><body>
		<h1>{{.Name}}</h1>
		<p>Price: ${{.Price}}</p>
		<div>{{.Desc}}</div>
		</body></html>
	`))
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("cat")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Validate sort parameter
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if !allowedSorts[sortBy] {
		sortBy = "id"
	}

	// Build query - category is parameterized, sort is validated above
	// min_price is used directly for numeric filtering
	baseQuery := "SELECT id, name, price, description FROM products WHERE category = $1"

	if minPrice != "" {
		// Developer note: min_price should always be numeric from the frontend slider
		baseQuery += " AND price >= " + minPrice
	}

	baseQuery += " ORDER BY " + sortBy + " LIMIT 50"

	rows, err := db.Query(baseQuery, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		products = append(products, p)
	}

	accept := r.Header.Get("Accept")
	if strings.Contains(accept, "application/json") {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(products)
	} else {
		w.Header().Set("Content-Type", "text/html")
		for _, p := range products {
			tmpl.Execute(w, p)
		}
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func adminResetHandler(w http.ResponseWriter, r *http.Request) {
	// Internal use only - resets demo data
	token := r.Header.Get("X-Admin-Token")
	expected := os.Getenv("ADMIN_TOKEN")
	if token != expected || expected == "" {
		http.Error(w, "forbidden", 403)
		return
	}
	_, err := db.Exec("TRUNCATE products; INSERT INTO products (name, price, category, description) VALUES ('Demo', 9.99, 'test', 'Demo product')")
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}
	w.Write([]byte("reset complete"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/admin/reset", adminResetHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Listening on :%s\n", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
